import requests

TIMEOUT_S = 10
RETRIES = 2


def charge(payload):
    for _ in range(RETRIES + 1):
        try:
            return requests.post("https://payments.example.invalid/charge", json=payload, timeout=TIMEOUT_S)
        except requests.Timeout:
            continue
    raise TimeoutError("payments API")

